def pane_label(node: str) -> str:
    """`Claude: <lane>`, `Claude: reviewer` for the default reviewer, `Claude: reviewer <id>` for a declared one."""
    if node == REVIEW:
        return "Claude: reviewer"
    if node.startswith("review-"):
        return f"Claude: reviewer {node[len('review-'):]}"
    return f"Claude: {node}"


def listed_rows(result: subprocess.CompletedProcess) -> list | None:
    """The rows of one `claude agents --json` answer, or None when it is not a listing: a nonzero exit, or output that is not a JSON list."""
    if result.returncode != 0:
        return None
    try:
        rows = json.loads(result.stdout)
    except (TypeError, ValueError):
        return None
    return rows if isinstance(rows, list) else None


class InteractiveSessions(ClaudeSessions):
    """Native Claude background sessions, not print-mode jobs or Herdr-owned agents."""

    def inventory(self) -> list[dict]:
        """`claude agents --json`. The listing only reads, so while the background service restarts (it exits nonzero,
        prints no list or hangs) it is asked again for the grace; a listing that stays unavailable is TransientInfraError.
        """
        try:
            response = run_claude([self.executable, "agents", "--json"], capture_output=True, text=True, timeout=15,
                                  retry_output=lambda result: listed_rows(result) is None)
        except subprocess.TimeoutExpired as error:
            raise TransientInfraError(f"Claude session inventory unavailable for {CLAUDE_MISSING_GRACE_SECONDS}s: {error}") from error
        rows = listed_rows(response)
        if rows is None:
            # Claude Code is unavailable, which says nothing about any session.
            answer = f"exited {response.returncode}" if response.returncode else "printed no session list"
            detail = ((response.stderr or "").strip() or (response.stdout or "").strip())[-300:]
            raise TransientInfraError(f"Claude session inventory unavailable for {CLAUDE_MISSING_GRACE_SECONDS}s: "
                                      f"`claude agents --json` {answer}" + (f": {detail}" if detail else ""))
        return rows

    def launch_name(self, node: str) -> str:
        """`workflow-<run>-<lane>`, `workflow-<run>-reviewer` for the default reviewer, `workflow-<run>-reviewer-<id>` otherwise."""
        if node == REVIEW:
            return f"workflow-{self.plan['run_id']}-reviewer"
        if node.startswith("review-"):
            return f"workflow-{self.plan['run_id']}-reviewer-{node[len('review-'):]}"
        return f"workflow-{self.plan['run_id']}-{node}"

    def node_worktree(self, node: str) -> Path:
        """Workers live in the plan's worktrees; every reviewer in the run's shared candidate checkout."""
        if is_review_node(node):
            return self.directory / "review-worktree"
        return Path(self.plan["nodes"][node]["worktree"])

    def locate(self, node: str, rows: list[dict]) -> dict | None:
        path = self.directory / f"{node}.interactive.json"
        if not path.exists():
            return None
        receipt = read_json(path)
        if receipt["plan_digest"] != plan_digest(self.plan):
            raise RuntimeError("Plan changed; cannot reconcile session")
        background_id = receipt.get("background_id")
        if not background_id:
            log = self.directory / f"{node}.launch.log"
            if not log.exists():
                return None
            # --bg assigns its own UUID. Bind the ID printed by this launch;
            # never adopt a guessed UUID or a name-only match.
            ids = set(re.findall(r"claude attach ([a-f0-9-]{8,36})\s", log.read_text(errors="replace")))
            if len(ids) != 1:
                raise RuntimeError("Missing/ambiguous native launch ID; reconcile manually")
            background_id = ids.pop()
        matches = [row for row in rows if row.get("id") == background_id]
        if not matches:
            return None
        if len(matches) != 1:
            raise RuntimeError("Ambiguous Claude session identity")
        row = matches[0]
        if row.get("kind") != "background" or Path(row.get("cwd", "")).resolve() != self.node_worktree(node).resolve() or row.get("name") != self.launch_name(node):
            raise RuntimeError("Claude session identity/worktree mismatch")
        if receipt.get("background_id") and row.get("sessionId") != receipt.get("session_id"):
            raise RuntimeError("Native Claude UUID changed; refusing attachment")
        if not isinstance(row.get("sessionId"), str) or not re.fullmatch(r"[a-f0-9-]{36}", row["sessionId"]):
            raise RuntimeError("Missing native Claude UUID")
        # `done` is a finished TURN, not a terminated terminal. Require the
        # native live PID as well; stale registry rows must not imply restart.
        if row.get("state") not in {"idle", "working", "blocked", "done"}:
            raise RuntimeError(f"Session is not attachable: {row.get('state')!r}; reconcile manually")
        pid = row.get("pid")
        if not isinstance(pid, int) or pid <= 0:
            raise RuntimeError("No live native PID; reconcile session before attaching")
        try:
            os.kill(pid, 0)
        except OSError as error:
            raise RuntimeError("Native process is unavailable; refusing implicit restart") from error
        return row

    settle_seconds = 30.0

    def settle(self, node: str) -> dict:
        """Bind the row created by the launch we just issued.

        `claude --bg` exits before the native session has fully registered: the
        inventory row can appear without a PID for a moment. Poll for the exact
        row until it is attachable; identity mismatches still fail immediately
        and nothing is ever launched again from here.
        """
        deadline = time.monotonic() + self.settle_seconds

        row = sessions.locate(node, rows)
        if row is None:
            raise RuntimeError(f"Cannot attach an unverified/missing reviewer session ({node})")
        allocate_reviewer_pane(sessions, mapping, mapping_path, node)
        attach_pane(sessions, mapping, mapping_path, node, row["sessionId"])
    return mapping


# A Claude Code update restarts the background service, which drops every attached client while the
# sessions run on (the restarted service adopts them), and about 15 seconds later respawns the idle ones
# onto the new binary under new PIDs. attach-one reattaches with a bounded backoff.
REATTACH_LIMIT = 30          # attempts in a row without a working attach before attach-one gives up
REATTACH_MAX_DELAY = 10      # seconds; the delay doubles from 2 up to this cap
ATTACH_STABLE_SECONDS = 60   # an attach that held this long was connected: its loss starts a new count
DEAD_PID_GRACE_SECONDS = 30  # an ended process with no new one listed: how long a respawn's new PID is awaited
# What a restarting service lists for a moment: a row still registering its PID, or in a state between two processes
# (starting, resuming). A failed listing is waited out whatever its error; a terminal state never is.
TRANSIENT_REFUSALS = ("No live native PID", "Session is not attachable")
TERMINAL_STATES = {"stopped", "failed"}
PROCESS_ENDED = "Native process is unavailable; refusing implicit restart"


class SessionGap(RuntimeError):
    """What a restarting background service shows for a while after an attach; waited out within REATTACH_LIMIT."""


class ProcessEnded(SessionGap):
    """The attached process ended with no new one listed (its PID, or no row): waited out for DEAD_PID_GRACE_SECONDS, then refused."""


def node_title(node: str) -> str:
    """`Worker <lane>`, `Reviewer review` for the default reviewer, `Reviewer <id>` for a declared one."""
    if node.startswith("review-"):
        return f"Reviewer {node[len('review-'):]}"
    return f"Reviewer {node}" if is_review_node(node) else f"Worker {node}"


def process_alive(pid) -> bool:
    """A PID from the session's own verified row; no PID (nothing attached yet) is never alive.

    kill(pid, 0) also answers for a process that has exited but is not collected yet (a zombie,
    for as long as its parent or, for an adopted session, init has not reaped it).
    """
    if not isinstance(pid, int) or pid <= 0:
        return False
    try:
        os.kill(pid, 0)
    except OSError:
        return False
    try:
        return Path(f"/proc/{pid}/stat").read_text().rsplit(")", 1)[1].split()[0] != "Z"
    except (OSError, IndexError):
        return True  # No /proc: kill(pid, 0) is all there is.


def recorded_stop(directory: Path, node: str) -> dict | None:
    """The controller's stop of this node's session as `{time, reason, confirmed, background_id}`, or None when it recorded none.

    `<node>.stop.json` is written before `claude stop` runs, so an attach that the stop itself ends
    already finds it; an unconfirmed intent counts too, since only the controller retries that stop.
    The time and reason come from the stop's timeline event (for workers stopped after a blocked
    wait, from that block), else from the marker.
    """
    marker = directory / f"{node}.stop.json"
    if not marker.is_file():
        return None
    try:
        intent = read_json(marker)
        confirmed = intent.get("stopped") is True
    except (ValueError, AttributeError):
        intent, confirmed = {}, False
    when = datetime.fromtimestamp(marker.stat().st_mtime, timezone.utc)
    reason = "stop recorded" if confirmed else "stop requested, not yet confirmed"
    path = directory / "events.jsonl"
    lines = path.read_text(errors="replace").splitlines() if confirmed and path.is_file() else []
    events = []
    for line in lines:
        try:
            events.append(json.loads(line))
        except ValueError:
            continue  # A line the controller was still writing.
    phase, prefix = (REVIEW, f"{node_title(node)} session stopped") if is_review_node(node) else ("freeze", "Native workers stopped")
    for index in range(len(events) - 1, -1, -1):
        event = events[index]
        if event.get("node") == phase and event.get("status") == "stopped" and str(event.get("message", "")).startswith(prefix):
            when, reason = datetime.fromisoformat(event["time"]), event["message"]
            previous = events[index - 1] if index else {}
            if previous.get("node") == "controller" and previous.get("status") == "blocked":
                reason = f"the run blocked: {previous['message']}"
            break
    return {"time": when.strftime("%Y-%m-%d %H:%M:%S UTC"), "reason": reason, "confirmed": confirmed,
            "background_id": intent.get("background_id")}


def stop_reported(directory: Path, node: str) -> bool:
    """Whether the controller recorded a stop of this node's session; if so, one line says so."""
    stop = recorded_stop(directory, node)
    if stop is None:
        return False
    if stop["confirmed"]:
        message = f"{node_title(node)} was stopped by the controller at {stop['time']} ({stop['reason']}); nothing to attach."
    else:
        message = (f"The controller is stopping {node} (requested at {stop['time']}, not yet confirmed); not attaching. "
                   f"Inspect it with `claude logs {stop['background_id']}` or `claude attach {stop['background_id']}`.")
    print(message, file=sys.stderr, flush=True)
    return True


def observe(sessions: InteractiveSessions, node: str, attached: dict | None) -> dict:
    """The session's verified live row; SessionGap while a restarting service cannot confirm it yet.

    Only a background id verified live and attached before (`attached`, its row then) earns that wait,
    whatever became of its PID, since an update respawns the session under a new one. How the listing
    itself fails (a missing CLI, a timeout, a non-zero exit, output it cannot parse) is Claude Code's
    business and every such failure is a gap, as are a row still registering its PID or in a state
    between two processes, a listing without the id while the attached process lives, and (ProcessEnded)
    a row still listing a PID whose process ended or a listing without the id once it ended. A first
    attach, a terminal state and every identity refusal fail at once: nothing is attached without a
    verified live row.
    """
    try:
        rows = sessions.inventory()
    except Exception as error:
        if attached is None:
            raise
        raise SessionGap(str(error)) from error
    try:
        row = sessions.locate(node, rows)
    except RuntimeError as error:
        if attached is None:
            raise
        if str(error).startswith(PROCESS_ENDED):
            raise ProcessEnded(PROCESS_ENDED) from error
        terminal = any(listed.get("id") == attached["id"] and listed.get("state") in TERMINAL_STATES for listed in rows)
        if terminal or not str(error).startswith(TRANSIENT_REFUSALS):
            raise
        raise SessionGap(str(error)) from error
    if row is None:
        if attached is None:
            raise RuntimeError("Session unavailable; refusing implicit restart")
        if not process_alive(attached["pid"]):
            # Without --all `claude agents` omits a finished (`done`) session that has no process: an idle one between
            # the two processes of an update's respawn, or one that ended.
            raise ProcessEnded("Session unavailable; refusing implicit restart")
        raise SessionGap(f"`claude agents` does not list {attached['id']}")
    if not process_alive(row["pid"]):  # A zombie passes locate's kill(pid, 0).
        raise ProcessEnded(PROCESS_ENDED) if attached is not None else RuntimeError(PROCESS_ENDED)
    return row


def attach_one(sessions: InteractiveSessions, node: str, *, clock=time.monotonic, sleep=time.sleep) -> None:
    """Attach one session in this terminal, and attach it again after a lost connection.

    `claude attach` exits 0 when the operator detaches (Ctrl+Z, or ← to the agent view) or the session
    ended, and non-zero when it loses the background service. After each attach the run's own records
    decide: a stop the controller recorded ends attach-one with one line, a live session the controller
    has not stopped is attached again after a bounded backoff (also after exit 0 when the service respawned
    it under a new PID: a detach never changes the PID), and a session gone without a recorded stop is
    refused. `claude attach` would wake a missing session, so only an exact live row is ever attached.
    """
    failures, attached = 0, None  # attached: the row of the last attach
    ended = None  # How the last attach ended ("detached", "interrupted" or "lost"); None once decided, or before the first.
    dead_since = last_error = None  # When a row was first seen listing an ended process; what made the latest attempt fail.
    while True:
        if stop_reported(sessions.directory, node):
            return
        try:
            row = observe(sessions, node, attached)
        except ProcessEnded as gap:
            # A respawn lists its new PID within seconds; a session that keeps missing a live process has ended.
            now = clock()
            dead_since = now if dead_since is None else dead_since
            if now - dead_since >= DEAD_PID_GRACE_SECONDS:
                raise
            row, last_error = None, str(gap)
        except SessionGap as gap:
            row, last_error = None, str(gap)
        else:
            dead_since = None
        respawned = row is not None and ended is not None and row["pid"] != attached["pid"]
        if ended == "interrupted" or (ended == "detached" and row is not None and not respawned):
            return  # The operator detached or interrupted the attach; the session keeps running.
        if row is not None and ended is None:
            if stop_reported(sessions.directory, node):
                return  # The controller's stop intent precedes `claude stop`: a session it is stopping is never attached.
            attached, started = row, clock()
            try:
                code = subprocess.run([sessions.executable, "attach", row["id"]], cwd=sessions.node_worktree(node)).returncode
                failure = f"`claude attach` exited {code}"
            except OSError as error:
                code, failure = 1, str(error)  # An update is replacing the CLI itself: retried like a lost connection.
            if clock() - started >= ATTACH_STABLE_SECONDS:
                failures = 0  # It was connected for a while: its end starts a new count.
            # An attach the operator interrupted (Ctrl+C: 130, or killed by SIGINT) is never retried.
            ended = "interrupted" if code in (130, -signal.SIGINT) else "detached" if code == 0 else "lost"
            if ended == "lost":
                last_error = failure
            continue  # The records decide first: a stop, or a session that ended, is never waited for.
        failures += 1
        if failures >= REATTACH_LIMIT:
            raise RuntimeError(f"Gave up reattaching {node} ({attached['id']}) after {REATTACH_LIMIT} attempts in a row; the session may still "
                               f"be running. Rerun attach-one once `claude agents` lists it again"
                               + (f"; last error: {last_error}" if last_error else ""))
        delay = min(2 ** failures, REATTACH_MAX_DELAY)
        if respawned:
            print(f"The background service respawned {node} ({attached['id']}) as PID {row['pid']}; reattaching in {delay}s…",
                  file=sys.stderr, flush=True)
        elif ended == "lost":
            print(f"Lost the connection to {node} ({attached['id']}); the background service may be restarting. Reattaching in {delay}s…",
                  file=sys.stderr, flush=True)
        else:
            print(f"The background service does not list {node} ({attached['id']}) yet; retrying in {delay}s…", file=sys.stderr, flush=True)
        if row is not None or ended != "detached":
            ended = None  # A detach stays undecided until a row shows whether the PID changed.
        sleep(delay)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("action", choices=["attach-one"])
    parser.add_argument("directory", type=Path)
    parser.add_argument("--node", help="attach-one: a worker lane of the run, or a reviewer node (review, or review-<id>)")
    args = parser.parse_args()
    directory = args.directory.resolve()
    # Every `claude` this process starts (the listing, `claude attach`) inherits the auto-updater off.
    os.environ.update(claude_env())
    try:
        sessions = InteractiveSessions(directory, timeout=45)
        if sessions.plan.get("mode") != "interactive":
            parser.error("Not an interactive run; prepare a new run instead of converting print-mode sessions")
        if not args.node or not sys.stdin.isatty():
            parser.error("attach-one requires --node and an interactive terminal")
        if args.node not in sessions.workers and args.node not in review_nodes(sessions.plan):
            parser.error(f"--node must be a lane of this run ({', '.join(sessions.workers)}) or {', '.join(review_nodes(sessions.plan))}")
        receipt = read_json(directory / f"{args.node}.interactive.json")
        if receipt["plan_digest"] != plan_digest(sessions.plan):
            raise RuntimeError("Plan changed; cannot attach")
        attach_one(sessions, args.node)
    except KeyboardInterrupt:
        parser.exit(130, f"\nattach-one interrupted; the {args.node} session keeps running (only the controller stops it).\n")
    except (RuntimeError, ValueError, OSError, subprocess.SubprocessError) as error:
        parser.exit(1, f"Blocked: {error}\nSession/worktree state retained at {directory}; no automatic stop or relaunch.\n")


if __name__ == "__main__":
    main()

def disabled_record(directory: Path, plan: dict) -> dict:
    return {"version": "1.0.0", "run_id": plan["run_id"], "status": "disabled", "attempt": 0, "session_id": None,
            "pinned": pinned_digests(directory, plan), "concerns": [], "simpler_alternative": None, "cheap_experiment": None,
            "accepted_reason": None, "decided_at": now()}


def challenge_gate(runtime) -> bool:
    """Called by `start` before any worker launch. True: launch the workers. False: the challenge paused the run.

    Runs without the plan's `challenge` key (every feature before 2.2.0 and every earlier run) pass untouched.
    """
    plan, directory = runtime.plan, runtime.directory
    if "challenge" not in plan:
        return True
    if (directory / REVISION_INTENT).exists():
        raise RuntimeError(f"{UNFINISHED_REVISION}; no worker launches before it does. Rerun it with: {resume_command(directory)}")
    current = load_challenge(directory)
    if plan["challenge"] is False:
        if current is None:
            save_challenge(directory, disabled_record(directory, plan))
            runtime.event("controller", "running", "Design challenge disabled by the feature (challenge: false)")
        return True
    if current is not None:
        if current["status"] in {"passed", "accepted"}:
            return True
        raise RuntimeError(f"The design challenge paused this run; edit the feature files, then: {resume_command(directory)}")
    if (directory / "challenge.running.json").exists():
        raise RuntimeError(f"A design challenge job was started and never decided; rerun it with: {resume_command(directory)}")
    return run_challenge(runtime, 1)["status"] == "passed"


def resume_command(directory: Path, herdr: bool = False, accept: bool = False) -> str:
    command = f"{sys.executable} -m workflow resume {directory}"
    if accept:
        command += ' --accept-challenge "<reason>"'
    return command + (" --herdr" if herdr else "")


def paused_message(directory: Path, herdr: bool = False) -> str:
    record = load_challenge(directory) or {}
    lines = [f"Design challenge attempt {record.get('attempt')} paused the run before any worker launch. Concerns:"]
    for severity in ("P0", "P1", "P2"):
        for concern in record.get("concerns", []):
            if concern["severity"] == severity:
                lines.append(f"  {severity} [{concern['kind']}] {concern['message']}\n      Consequence: {concern['consequence']}")
    lines.append(f"Simpler alternative: {record.get('simpler_alternative')}")
    lines.append(f"Cheap experiment: {record.get('cheap_experiment')}")
    lines.append("Edit the task files, decisions.md or the PRD, then rerun the challenge:\n  " + resume_command(directory, herdr))
    lines.append("Or record an override and launch the workers:\n  " + resume_command(directory, herdr, accept=True))
    return "\n".join(lines)


def read_pinned(plan: dict) -> tuple[dict[str, str], str]:
    """The lanes' tasks and decisions.md as the paths pinned at prepare hold them now; refused as prepare refuses them."""
    tasks = {}
    for node in plan_workers(plan):
        path = Path(plan["task_files"][node])
        text = path.read_text()
        problems = brief_problems(text)
        if problems:
            raise ValueError(f"{path}: {', '.join(problems)}")
        tasks[node] = text
    decisions = Path(plan["decisions"]["path"])
    text = decisions.read_text()
    if not text.strip():
        raise ValueError(f"{decisions} is empty")
    if plan.get("prd") and not Path(plan["prd"]["path"]).is_file():
        raise ValueError(f"PRD {plan['prd']['path']} does not exist")
    return tasks, text


def repin(directory: Path, plan: dict, policy: dict) -> dict:
    """Re-read the task files, decisions.md and the PRD from the paths pinned at prepare; the policy is never re-pinned.

    One plan.json write, which also saves the base `move_base` set in `plan`: the base and the pinned files move together.
    """
    workers = {worker["node_id"]: worker for worker in policy["workers"]}
    tasks, decisions = read_pinned(plan)
    for node, text in tasks.items():
        plan["nodes"][node]["task"] = pinned_task(text, workers[node])
    plan["decisions"]["text"] = decisions
    if plan.get("prd"):
        plan["prd"] = pin_prd(directory, Path(plan["prd"]["path"]))
    save_json(directory / "plan.json", plan)
    return plan


# ---- Revised feature files: `resume` commits them and moves the run to that commit ------------------------------

def pinned_paths(plan: dict) -> set[str]:
    """The paths `repin` reads (the lanes' task files, decisions.md, the PRD) that lie in the source checkout, repository-relative."""
    repo = Path(plan["repository"])
    files = [*plan["task_files"].values(), plan["decisions"]["path"], *([plan["prd"]["path"]] if plan.get("prd") else [])]
    return {Path(path).relative_to(repo).as_posix() for path in files if Path(path).is_relative_to(repo)}


def dirty_paths(repo: Path) -> list[str]:
    """Every path `git status` reports: staged or unstaged changes (a rename as both of its paths) and untracked files."""
    output = subprocess.check_output(["git", "-C", str(repo), "status", "--porcelain", "-z", "--no-renames", "--untracked-files=all"], text=True)
    return sorted({entry[3:] for entry in output.split("\0") if entry})


def commits_after(repo: Path, base: str) -> list[str] | None:
    """The commits of the checked-out branch after `base`, oldest first; None when the branch no longer contains `base`."""
    if subprocess.run(["git", "-C", str(repo), "merge-base", "--is-ancestor", base, "HEAD"], capture_output=True).returncode != 0:
        return None
    return git(repo, "rev-list", "--reverse", f"{base}..HEAD").split()


def revision_subject(run_id: str) -> str:
    return f"Workflow {run_id}: feature files revised"


def is_revision(repo: Path, commit: str, plan: dict) -> bool:
    """A commit `resume` made for this run: one parent, the pipeline's identity and subject, only the pinned feature files."""
    from .pipeline import commit_env
    parents = git(repo, "rev-list", "--parents", "-n", "1", commit).split()[1:]
    author, _, subject = git(repo, "log", "-1", "--format=%an%n%s", commit).partition("\n")
    paths = subprocess.check_output(["git", "-C", str(repo), "diff-tree", "--no-commit-id", "--no-renames", "--name-only", "-r", "-z", commit], text=True)
    return (len(parents) == 1 and author == commit_env()["GIT_AUTHOR_NAME"] and subject.startswith(revision_subject(plan["run_id"]))
            and set(filter(None, paths.split("\0"))) <= pinned_paths(plan))


def commit_revision(runtime, answered: int) -> None:
    """`resume` after an edit: commit the edited feature files on the run's branch, then move the run's worktrees to that commit.

    Only the paths `repin` reads may be changed and every run worktree must be a clean checkout of the base; anything
    else is refused before anything is written. Then `challenge-revision.json` records the move until `repin` has
    pinned its result: while it exists `start` and `--accept-challenge` refuse, so no worker launches on a half-moved
    run, and a rerun continues from the revisions the branch already carries without a second commit.
    """
    from .pipeline import commit_env
    directory, plan = runtime.directory, runtime.plan
    repo, base, branch = Path(plan["repository"]), plan["base_commit"], plan["source_branch"]
    head = subprocess.run(["git", "-C", str(repo), "symbolic-ref", "-q", "--short", "HEAD"], capture_output=True, text=True).stdout.strip()
    if head != branch:
        raise ValueError(f"The source checkout is not on the run's branch {branch}{'' if head else ' (its HEAD is detached)'}; switch back before resume")
    dirty = dirty_paths(repo)
    others = [path for path in dirty if path not in pinned_paths(plan)]
    if others:
        raise ValueError(f"The source checkout has changes resume does not re-pin: {', '.join(others)}. Only the task files, "
                         "decisions.md and the PRD pinned at prepare may change before resume; stash or revert the rest")
    earlier = commits_after(repo, base)
    if earlier is None or not all(is_revision(repo, commit, plan) for commit in earlier):
        raise ValueError(f"The branch {branch} moved past the run's base {base} with commits resume did not make; resume commits the "
                         f"revised feature files itself. Reset the branch to the base (git reset --soft {base}) and rerun resume")
    check_run_worktrees(runtime, {base, *earlier})  # Before the commit: a refusal leaves the branch and the edits as they were.
    intent = directory / REVISION_INTENT
    previous = read_json(intent) if intent.exists() else {"base_commit": base, "paths": []}
    save_json(intent, {"base_commit": previous["base_commit"], "paths": sorted({*previous["paths"], *dirty})})
    if dirty:
        parent = git(repo, "rev-parse", "HEAD")
        subject = revision_subject(plan["run_id"]) + (f" after design challenge attempt {answered}" if answered else " before the design challenge")
        command = ["git", "-C", str(repo), "--literal-pathspecs", "-c", "core.hooksPath=/dev/null", "-c", "commit.gpgsign=false"]
        subprocess.run([*command, "add", "-A", "--", *dirty], env=commit_env(), check=True, capture_output=True)
        subprocess.run([*command, "commit", "-q", "-m", subject, "--", *dirty], env=commit_env(), check=True, capture_output=True)
        commit = git(repo, "rev-parse", "HEAD")
        if git(repo, "rev-parse", f"{commit}^") != parent or not is_revision(repo, commit, plan) or git(repo, "status", "--porcelain"):
            raise RuntimeError(f"Revision commit {commit} is not exactly the edited feature files; reconcile the source checkout before resume")
        runtime.event(CHALLENGE, "running", f"Revised feature files committed on {branch} as {commit}: {', '.join(dirty)}")
    target = git(repo, "rev-parse", "HEAD")
    if target != base:
        move_base(runtime, target, {base, *earlier})


def run_worktrees(repo: Path, directory: Path) -> list[Path]:
    """The repository's worktrees inside the run directory: before any launch, the lane worktrees and the challenge worktree."""
    listing = subprocess.check_output(["git", "-C", str(repo), "worktree", "list", "--porcelain", "-z"], text=True)
    paths = [Path(field[len("worktree "):]) for field in listing.split("\0") if field.startswith("worktree ")]
    return sorted(path for path in paths if path.resolve().is_relative_to(directory))


def check_run_worktrees(runtime, heads: set[str]) -> dict[Path, str]:
    """Every worktree of the run (the lanes' and the challenge's) registered, present and a clean checkout of one of `heads`; their heads."""
    directory, plan = runtime.directory, runtime.plan
    repo, base = Path(plan["repository"]), plan["base_commit"]
    worktrees = run_worktrees(repo, directory)
    lanes = [Path(plan["nodes"][node]["worktree"]).resolve() for node in plan_workers(plan)]
    missing = [str(path) for path in lanes if path not in [item.resolve() for item in worktrees]]
    if missing:
        raise RuntimeError(f"Lane worktrees are not registered in {repo}: {', '.join(missing)}; reconcile before resume")
    found = {}
    for path in worktrees:
        if not path.is_dir():
            raise RuntimeError(f"Run worktree {path} is registered but missing; reconcile before resume")
        found[path] = git(path, "rev-parse", "HEAD")
        if found[path] not in heads or git(path, "status", "--porcelain"):
            raise RuntimeError(f"Run worktree {path} is not a clean checkout of the base {base}; reconcile before resume")
    return found


def move_base(runtime, target: str, heads: set[str]) -> None:
    """Check out `target` in every worktree of the run and set it as the plan's base and each lane's start commit, as prepare does.

    `repin` saves them in the same plan.json write as the re-pinned files. Every worktree must be a clean checkout of
    one of `heads` (the base and the revisions), or of `target` when an interrupted move already reached it.
    """
    plan = runtime.plan
    base = plan["base_commit"]
    found = check_run_worktrees(runtime, {*heads, target})
    for path, head in found.items():
        if head != target:
            subprocess.run(["git", "-C", str(path), "-c", "core.hooksPath=/dev/null", "checkout", "-q", "--detach", target], check=True, capture_output=True)
        if git(path, "rev-parse", "HEAD") != target or git(path, "status", "--porcelain"):
            raise RuntimeError(f"Run worktree {path} did not move cleanly to {target}")
    plan["base_commit"] = target
    for node in plan_workers(plan):
        plan["nodes"][node]["observed_start_commit"] = git(Path(plan["nodes"][node]["worktree"]), "rev-parse", "HEAD")
    runtime.event(CHALLENGE, "running", f"Run worktrees moved from base {base} to {target} ({len(found)}); plan.json pins it with the "
                                        "re-pinned files next; no worker exists yet")


def changed_pins(plan: dict, policy: dict) -> list[Path]:
    """The pinned feature files that no longer hold the plan's copies: edited, committed without `resume`, or removed."""
    workers = {worker["node_id"]: worker for worker in policy["workers"]}
    changed = []
    for node in plan_workers(plan):
        path = Path(plan["task_files"][node])
        if not path.is_file() or pinned_task(path.read_text(), workers[node]) != plan["nodes"][node]["task"]:
            changed.append(path)
    decisions = Path(plan["decisions"]["path"])
    if not decisions.is_file() or decisions.read_text() != plan["decisions"]["text"]:
        changed.append(decisions)
    prd = plan.get("prd")
    if prd and (not Path(prd["path"]).is_file() or digest_bytes(Path(prd["path"]).read_bytes()) != prd["sha256"]):
        changed.append(Path(prd["path"]))
    return changed


def refuse_unused_edits(directory: Path, plan: dict, policy: dict) -> None:
    """An override launches the workers on the plan's pinned copies at its base; an unfinished resume, an unused revision or a changed pin refuses it."""
    repo = Path(plan["repository"])
    if (directory / REVISION_INTENT).exists():
        raise ValueError(f"{UNFINISHED_REVISION}; rerun resume without --accept-challenge to finish it")
    pending = [commit for commit in commits_after(repo, plan["base_commit"]) or [] if is_revision(repo, commit, plan)]
    if pending:
        raise ValueError(f"An interrupted resume committed revised feature files ({', '.join(pending)}) that this run does not use yet; "
                         "rerun resume without --accept-challenge to finish moving the run to them")
    edited = {path for path in dirty_paths(repo) if path in pinned_paths(plan)}
    edited |= {path.relative_to(repo).as_posix() if path.is_relative_to(repo) else str(path) for path in changed_pins(plan, policy)}
    if edited:
        raise ValueError(f"Feature files changed since they were pinned ({', '.join(sorted(edited))}); the override would launch the workers "
                         "without them. Rerun resume without --accept-challenge to commit them and rerun the challenge, or revert them")


def launched_workers(directory: Path, plan: dict) -> list[str]:
    """Lanes with a launch receipt, which InteractiveSessions saves before `claude --bg`. `<lane>.json` is none: only the
    legacy print workers write it, and a lane may share its name with a run file (plan.json, policy.json, terminals.json)."""
    return [node for node in plan_workers(plan) if (directory / f"{node}.interactive.json").exists()]


def resume_challenge(runtime, accept_reason: str | None = None) -> dict:
    """`resume`: rerun the challenge on the re-pinned feature files as the next attempt, or record `accepted` with a reason.

    Only before any worker launch. Edited feature files are committed on the run's branch first and the run moves to
    that commit, so the source checkout stays clean for integration. A challenge that already passed or was accepted
    is returned as it is. The override accepts only an attempt that read what the plan pins now: a rerun that failed
    after its re-pin leaves the paused record of the previous attempt, which read other files.
    """
    directory, plan = runtime.directory, runtime.plan
    if not has_challenge(plan):
        raise ValueError("This run has no design challenge to resume (feature.json before 2.2.0, or challenge: false)")
    launched = launched_workers(directory, plan)
    if launched:
        raise ValueError(f"Workers already launched ({', '.join(launched)}); resume applies only before any worker starts")
    current = load_challenge(directory)
    if current is not None and current["status"] in {"passed", "accepted"}:
        return current
    if accept_reason is not None:
        if not accept_reason.strip():
            raise ValueError("--accept-challenge needs a non-empty reason")
        if current is None or current["status"] != "paused":
            raise ValueError("Only a paused design challenge can be accepted")
        refuse_unused_edits(directory, plan, runtime.policy)
        changed = [key.removesuffix("_sha256") for key, value in pinned_digests(directory, plan).items() if current["pinned"].get(key) != value]
        if changed:
            raise ValueError(f"Design challenge attempt {current['attempt']} read other feature files than the plan now pins ({', '.join(changed)}): "
                             "a later resume re-pinned them and its challenge decided nothing. The override would launch the workers on "
                             "files no challenge read; rerun resume without --accept-challenge")
        record = {**current, "status": "accepted", "accepted_reason": accept_reason.strip(), "decided_at": now()}
        save_challenge(directory, record)
        runtime.event(CHALLENGE, "succeeded", f"Design challenge attempt {record['attempt']} accepted by the operator: {record['accepted_reason']}")
        return record
    running = directory / "challenge.running.json"
    attempt = max(current["attempt"] if current else 0, read_json(running)["attempt"] if running.exists() else 0) + 1
    read_pinned(plan)  # A brief that lost a required section is refused before anything is committed.
    commit_revision(runtime, attempt - 1)
    repin(directory, plan, runtime.policy)  # The moved base and the re-pinned files in one plan.json write.
    (directory / REVISION_INTENT).unlink()
    runtime.event(CHALLENGE, "running", f"Feature files re-pinned for design challenge attempt {attempt} on base {plan['base_commit']}")
    return run_challenge(runtime, attempt)


